43	
44	/**
45	 * A simple JDBC-based implementation of the {@link OwnerRepository} interface.
46	 *
47	 * @author Ken Krebs
48	 * @author Juergen Hoeller
49	 * @author Rob Harrop
50	 * @author Sam Brannen
51	 * @author Thomas Risberg
52	 * @author Mark Fisher
53	 * @author Antoine Rey
54	 * @author Vitaliy Fedoriv
55	 */
56	@DependsOnDatabaseInitialization
57	@Repository
58	@Profile("jdbc")
59	public class JdbcOwnerRepositoryImpl implements OwnerRepository {
60	
61	    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;
62	
63	    private SimpleJdbcInsert insertOwner;
64	
65	    public JdbcOwnerRepositoryImpl(DataSource dataSource) {
66	
67	        this.insertOwner = new SimpleJdbcInsert(dataSource)
68	            .withTableName("owners")
69	            .usingGeneratedKeyColumns("id");
70	
71	        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);
72	
73	    }
74	
75	
76	    /**
77	     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
78	     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
79	     * already loaded.
80	     */
81	    @Override
82	    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
83	        Map<String, Object> params = new HashMap<>();
84	        params.put("lastName", lastName + "%");
85	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
86	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE last_name like :lastName",
87	            params,
88	            BeanPropertyRowMapper.newInstance(Owner.class)
89	        );
90	        loadOwnersPetsAndVisits(owners);
91	        return owners;
92	    }
93	
94	    @Override
95	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
96	        Map<String, Object> params = new HashMap<>();
97	        params.put("lastName", lastName + "%");
98	        params.put("size", pageable.getPageSize());
99	        params.put("offset", pageable.getOffset());
100	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
101	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
102	            params,
103	            BeanPropertyRowMapper.newInstance(Owner.class)
104	        );
105	        loadOwnersPetsAndVisits(owners);
106	        Long total = this.namedParameterJdbcTemplate.queryForObject(
107	            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
108	            params,
109	            Long.class
110	        );
111	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
112	    }
113	
114	    /**
115	     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
116	     * for the corresponding owner, if not already loaded.
117	     */
118	    @Override
119	    public Owner findById(int id) throws DataAccessException {
120	        Owner owner;
121	        try {
122	            Map<String, Object> params = new HashMap<>();
123	            params.put("id", id);
124	            owner = this.namedParameterJdbcTemplate.queryForObject(
125	                "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE id= :id",
126	                params,
127	                BeanPropertyRowMapper.newInstance(Owner.class)
128	            );
129	        } catch (EmptyResultDataAccessException ex) {
130	            throw new ObjectRetrievalFailureException(Owner.class, id);
131	        }
132	        loadPetsAndVisits(owner);
133	        return owner;
134	    }
135	
136	    public void loadPetsAndVisits(final Owner owner) {
137	        Map<String, Object> params = new HashMap<>();
138	        params.put("id", owner.getId());
139	        final List<JdbcPet> pets = this.namedParameterJdbcTemplate.query(
140	            "SELECT pets.id as pets_id, name, birth_date, type_id, owner_id, visits.id as visit_id, visit_date, description, visits.pet_id as visits_pet_id FROM pets LEFT OUTER JOIN visits ON pets.id = visits.pet_id WHERE owner_id=:id ORDER BY pets.id",
141	            params,
142	            new JdbcPetVisitExtractor()
143	        );
144	        Collection<PetType> petTypes = getPetTypes();
145	        for (JdbcPet pet : pets) {
146	            pet.setType(EntityUtils.getById(petTypes, PetType.class, pet.getTypeId()));
147	            owner.addPet(pet);
148	        }
149	    }
150	
151	    @Override
152	    public Collection<Owner> findByTelephone(String telephone) throws DataAccessException {
153	        Map<String, Object> params = new HashMap<>();
154	        params.put("telephone", telephone);
155	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
156	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners WHERE telephone = :telephone",
157	            params,
158	            BeanPropertyRowMapper.newInstance(Owner.class)
159	        );
160	        loadOwnersPetsAndVisits(owners);
161	        return owners;
162	    }
163	
164	    @Override
165	    public void save(Owner owner) throws DataAccessException {
166	        BeanPropertySqlParameterSource parameterSource = new BeanPropertySqlParameterSource(owner);
167	        if (owner.isNew()) {
168	            Number newKey = this.insertOwner.executeAndReturnKey(parameterSource);
169	            owner.setId(newKey.intValue());
170	        } else {
171	            this.namedParameterJdbcTemplate.update(
172	                "UPDATE owners SET first_name=:firstName, last_name=:lastName, address=:address, " +
173	                    "city=:city, telephone=:telephone, email=:email WHERE id=:id",
174	                parameterSource);
175	        }
176	    }
177	
178	    public Collection<PetType> getPetTypes() throws DataAccessException {
179	        return this.namedParameterJdbcTemplate.query(
180	            "SELECT id, name FROM types ORDER BY name", new HashMap<String, Object>(),
181	            BeanPropertyRowMapper.newInstance(PetType.class));
182	    }
183	
184	    /**
185	     * Loads the {@link Pet} and {@link Visit} data for the supplied {@link List} of {@link Owner Owners}.
186	     *
187	     * @param owners the list of owners for whom the pet and visit data should be loaded
188	     * @see #loadPetsAndVisits(Owner)
189	     */
190	    private void loadOwnersPetsAndVisits(List<Owner> owners) {
191	        for (Owner owner : owners) {
192	            loadPetsAndVisits(owner);
193	        }
194	    }
195	
196		@Override
197		public Collection<Owner> findAll() throws DataAccessException {
198			List<Owner> owners = this.namedParameterJdbcTemplate.query(
199		            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners",
200		            new HashMap<String, Object>(),
201		            BeanPropertyRowMapper.newInstance(Owner.class));
202			for (Owner owner : owners) {
203	            loadPetsAndVisits(owner);
204	        }
205		    return owners;
206		}
207	
208	    @Override
209	    public Page<Owner> findAll(Pageable pageable) throws DataAccessException {
210	        Map<String, Object> params = new HashMap<>();
211	        params.put("size", pageable.getPageSize());
212	        params.put("offset", pageable.getOffset());
213	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
214	            "SELECT id, first_name, last_name, address, city, telephone, email FROM owners ORDER BY id LIMIT :size OFFSET :offset",
215	            params,
216	            BeanPropertyRowMapper.newInstance(Owner.class));
217	        loadOwnersPetsAndVisits(owners);
218	        Long total = this.namedParameterJdbcTemplate.queryForObject(
219	            "SELECT COUNT(*) FROM owners",
220	            params,
221	            Long.class
222	        );
223	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
224	    }
225	
226		@Override
227		@Transactional
228		public void delete(Owner owner) throws DataAccessException {
229			Map<String, Object> ownerParams = new HashMap<>();
230			ownerParams.put("id", owner.getId());
231	        List<Pet> pets = owner.getPets();
232	        // cascade delete pets
233	        for (Pet pet : pets){
234	        	Map<String, Object> petParams = new HashMap<>();
235	        	petParams.put("id", pet.getId());
236	        	// cascade delete visits
